-- Synthetic isolated fixture shared by PGlite and native PostgreSQL.
 create role anon;create role authenticated;create role service_role;
 create schema icash_recording_private;
 create table icash_operating_budget(id integer primary key,enabled boolean);insert into icash_operating_budget values(1,true);
 create table icash_accounts(id uuid primary key,bot_paused boolean default false);
 create table icash_wallets(account_id uuid primary key,balance_cents bigint default 10000,reserved_cents bigint default 0);
 create table icash_voice_configs(account_id uuid primary key,enabled boolean default true);
 create table icash_voice_scheduler(id integer primary key,last_dispatch_at timestamptz);insert into icash_voice_scheduler(id) values(1);
 create table icash_voice_jobs(id uuid primary key,account_id uuid,permission_id uuid,operational_contact_id uuid,state text default 'ready',due_at timestamptz,updated_at timestamptz,callback_id uuid,sms_source_message_id uuid,cancellation_notice_id uuid,meta_offer_lead_id uuid,meta_followup_lead_id uuid,outcome text);
 create index icash_voice_due on icash_voice_jobs(due_at) where state='ready';
 create unique index icash_voice_jobs_callback_id_key on icash_voice_jobs(callback_id);
 create unique index icash_voice_jobs_cancellation_notice_id_key on icash_voice_jobs(cancellation_notice_id);
 create unique index icash_voice_sms_source_once on icash_voice_jobs(sms_source_message_id) where not(state='canceled' and not(outcome is distinct from 'context_rejected_before_dial'));
 create table icash_contact_permissions(id uuid primary key,account_id uuid,screening_id uuid,contact_key text,party text default 'seller',timezone text,revoked_at timestamptz,permission_until timestamptz,seller_intake_id uuid);
 create table icash_operational_contacts(id uuid primary key,account_id uuid,screening_id uuid,contact_key text,timezone text,timezone_basis text,channel text,revoked_at timestamptz,eligibility_until timestamptz);
 create view icash_voice_contact_targets as select id,account_id,screening_id,contact_key,party,timezone,revoked_at,permission_until,'operator_record'::text eligibility_source from icash_contact_permissions union all select id,account_id,screening_id,contact_key,'seller',timezone,revoked_at,eligibility_until,'operational_checks_only' from icash_operational_contacts where channel='voice';
 create table icash_screening_jobs(id uuid primary key,account_id uuid,state text);
 create table icash_meta_leads(lead_id uuid,account_id uuid,screening_id uuid,voice_job_id uuid);
 create table icash_live_callbacks(id uuid primary key,account_id uuid,screening_id uuid,conversation_id uuid,state text,due_at timestamptz);
 create table icash_live_conversations(id uuid primary key,account_id uuid,screening_id uuid,contact_key text,party text,state text,result jsonb,completed_at timestamptz);
 create table icash_automation_tickets(id uuid primary key default gen_random_uuid(),account_id uuid,kind text,voice_job_id uuid,token text default gen_random_uuid()::text,created_at timestamptz default now());
 create index icash_automation_voice_account_recent on icash_automation_tickets(account_id,created_at desc) where kind='voice_dispatch';
 create table fixture_guards(job_id uuid,kind text);
 create sequence fixture_window_checks;
 create function icash_outreach_window_open(text,text,timestamptz) returns boolean language plpgsql as $$begin perform nextval('public.fixture_window_checks');return $1='open';end$$;
 create function icash_owner_demo_call_current(uuid,uuid) returns boolean language sql as $$select false$$;
 create function icash_queue_voice_jobs() returns void language sql as $$select$$;
 create function icash_outgoing_voice_capacity_open() returns boolean language sql as $$select true$$;
 create function icash_recording_private.voice_capacity_snapshot() returns jsonb language sql as $$select '{}'::jsonb$$;
 create function icash_recording_private.voice_queue_slot_from_snapshot(uuid,uuid,jsonb) returns boolean language sql stable as $$select not exists(select 1 from public.fixture_guards where job_id=$2 and kind='capacity')$$;
 create function icash_seller_phone_call_current(uuid,uuid) returns boolean language sql stable as $$select not exists(select 1 from public.fixture_guards where job_id=$2 and kind='phone')$$;
 create function icash_requested_seller_call_current(uuid,uuid) returns boolean language sql stable as $$select not exists(select 1 from public.fixture_guards where job_id=$2 and kind='request')$$;
 create function icash_cancellation_voice_current(uuid,text) returns boolean language sql stable as $$select not exists(select 1 from public.fixture_guards where 'voice:'||job_id=$2 and kind='cancellation')$$;
 create function icash_call_has_seller_response(jsonb) returns boolean language sql immutable as $$select $1->'human'='true'::jsonb$$;
 create table icash_operation_spend(operation_key text primary key,state text,charged_cents bigint);
 insert into icash_operation_spend values('unchanged-unknown','dispatched',null),('unchanged-settled','settled',27);
